import{_ as l,a0 as t,w as o,s as d,I as n,x as a,a1 as i,A as p,ao as c}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"使用 cowsay 命令的 3 种有趣方式 | LCTT x X-CMD","titleTemplate":false,"description":"使用 cowsay 命令的 3 种有趣方式 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 cowsay 命令的 3 种有趣方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 cowsay 命令的 3 种有趣方式 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211117 3 interesting ways to use the Linux cowsay command","title":"使用 cowsay 命令的 3 种有趣方式","tag":"202111","desc":""},"relativePath":"202111/20211117 3 interesting ways to use the Linux cowsay command.md","filePath":"[post].md"}'),r={name:"202111/20211117 3 interesting ways to use the Linux cowsay command.md"};function h(g,s,u,k,b,y){const e=t("Link");return o(),d("div",null,[s[22]||(s[22]=n("h1",{id:"使用-cowsay-命令的-3-种有趣方式",tabindex:"-1"},[a("使用 cowsay 命令的 3 种有趣方式 "),n("a",{class:"header-anchor",href:"#使用-cowsay-命令的-3-种有趣方式","aria-label":"Permalink to “使用 cowsay 命令的 3 种有趣方式”"},"​")],-1)),s[23]||(s[23]=n("blockquote",null,[n("p",null,"想试一个只是好玩的应用吗？试试 cowsay。")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202111/25/232451f6v8fnne2np8e22e.jpg",alt:""})],-1)),n("p",null,[s[2]||(s[2]=a("大多数时候，终端是一个生产力的动力源。但是，终端的作用不止是命令和配置。在所有杰出的开源软件中，有些是 ",-1)),i(e,{href:"https://opensource.com/life/16/6/fun-and-semi-useless-toys-linux"},{default:p(()=>[...s[0]||(s[0]=[a("为了好玩而写的",-1)])]),_:1}),s[3]||(s[3]=a("。我以前介绍过一些 ",-1)),i(e,{href:"https://opensource.com/article/21/11/fun-linux-commands"},{default:p(()=>[...s[1]||(s[1]=[a("有趣的命令",-1)])]),_:1}),s[4]||(s[4]=a("，但这篇文章只讲一个：古老的 ",-1)),s[5]||(s[5]=n("code",null,"cowsay",-1)),s[6]||(s[6]=a(" 命令。",-1))]),s[25]||(s[25]=c(`<p><code>cowsay</code> 是一只可配置的会说话（或思考）的牛。它接受一个文本字符串，并输出一个牛说话的图形。下面是一头牛在说它喜欢 Linux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; I love Linux &gt;</span></span>
<span class="line"><span>--------------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (oo)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>               ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><p>要得到这个结果，我只需输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay &quot;I love Linux&quot;</span></span></code></pre></div><h3 id="在-linux-上安装-cowsay" tabindex="-1">在 Linux 上安装 cowsay <a class="header-anchor" href="#在-linux-上安装-cowsay" aria-label="Permalink to “在 Linux 上安装 cowsay”">​</a></h3><p>你可以用你的包管理器安装 <code>cowsay</code>。在 Debian、Mint、Elementary 和类似的发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cowsay</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install cowsay-beefymiracle</span></span></code></pre></div><h3 id="cowsay-命令选项" tabindex="-1">Cowsay 命令选项 <a class="header-anchor" href="#cowsay-命令选项" aria-label="Permalink to “Cowsay 命令选项”">​</a></h3><p><code>cowsay</code> 是一个简单又有点傻的应用。除了为你的终端机提供一些不同样式外，它并没有什么实际用途。例如，与其让一头普通的牛说一个有趣短语，你可以让一头长着古怪眼睛的牛说一个有趣的短语。输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay -e @@ Hello</span></span></code></pre></div><p>你会看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; Hello &gt;</span></span>
<span class="line"><span> -------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (@@)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>               ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><p>或者你可以让它伸出舌头。输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay -T U Hello</span></span></code></pre></div><p>你会看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; Hello &gt;</span></span>
<span class="line"><span>-------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (oo)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>            U ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><p>更好的是，你可以将 <code>fortune</code> 命令与 <code>cowsay</code> 结合起来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fortune | cowsay</span></span></code></pre></div><p>现在你有了一头特别睿智的牛：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> _______________________________________</span></span>
<span class="line"><span>/ we:                                   \\</span></span>
<span class="line"><span>|                                       |</span></span>
<span class="line"><span>| The single most important word in the |</span></span>
<span class="line"><span>\\ world.                                /</span></span>
<span class="line"><span> ---------------------------------------</span></span>
<span class="line"><span>       \\   ^__^</span></span>
<span class="line"><span>        \\  (oo)\\_______</span></span>
<span class="line"><span>           (__)\\       )\\/\\</span></span>
<span class="line"><span>               ||----w |</span></span>
<span class="line"><span>               ||     ||</span></span></code></pre></div><h3 id="结实的奇迹" tabindex="-1">“结实的奇迹” <a class="header-anchor" href="#结实的奇迹" aria-label="Permalink to ““结实的奇迹””">​</a></h3><p>在 Fedora 上，有一个额外的 <code>cowsay</code> 选项，也是一个非官方的项目吉祥物。多年来，Fedora 安装程序一直在展示宣传开源贡献的幻灯片。因为它们是根据汽车电影院的插曲设计的，所以幻灯片中常见的卡通人物是拟人化的热狗。</p><p>为了与这个主题保持一致，你可以用 Fedora 版本的 <code>cowsay</code> 调用一个所谓的“<ruby>结实的奇迹<rt>beefy miracle</rt></ruby>”。（LCTT 译注：Fedora 17 的开发代号。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cowsay -f beefymiracle Hello Fedora</span></span></code></pre></div><p>你会得到一个非常傻的输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt; Hello Fedora &gt;</span></span>
<span class="line"><span> --------------      .---. __</span></span>
<span class="line"><span>          ,    \\    /     \\   \\    ||||</span></span>
<span class="line"><span>         \\\\\\\\      |O___O |    | \\\\||||</span></span>
<span class="line"><span>         \\   //    | \\_/  |    |  \\   /</span></span>
<span class="line"><span>          &#39;--/----/|     /     |   |-&#39;</span></span>
<span class="line"><span>                 //</span><span> //  /     -----&#39;</span></span>
<span class="line"><span>                //  \\\\ /      /</span></span>
<span class="line"><span>               //</span><span>  // /      /</span></span>
<span class="line"><span>              //  \\\\ /      /</span></span>
<span class="line"><span>             //</span><span>  // /      /</span></span>
<span class="line"><span>            /|   &#39; /      /</span></span>
<span class="line"><span>            //\\___/      /</span></span>
<span class="line"><span>           //   ||\\     /</span></span>
<span class="line"><span>           \\\\_  || &#39;---&#39;</span></span>
<span class="line"><span>           /&#39; /  \\\\_.-</span></span>
<span class="line"><span>          /  /    --| |</span></span>
<span class="line"><span>          &#39;-&#39;      |  |</span></span>
<span class="line"><span>                    &#39;-&#39;</span></span></code></pre></div><h3 id="图形化的-cowsay" tabindex="-1">图形化的 cowsay <a class="header-anchor" href="#图形化的-cowsay" aria-label="Permalink to “图形化的 cowsay”">​</a></h3><p>如果你发现自己需要用图形化的牛来传递信息，可以使用 <code>xcowsay</code> 命令。这是一个类似于 <code>cowsay</code> 的图形程序，它接受一个由用户输入的文本字符串，或从另一个应用（如 Fortune）输送过来的文本字符串。</p><p><img src="https://opensource.com/sites/default/files/uploads/graphical_cowsay.png" alt="A cartoon cow has a speech bubble that reads &quot;I love Linux&quot;" title="graphical cowsay"></p><h3 id="有趣的-linux-命令" tabindex="-1">有趣的 Linux 命令 <a class="header-anchor" href="#有趣的-linux-命令" aria-label="Permalink to “有趣的 Linux 命令”">​</a></h3><p>虽然 <code>cowsay</code> 不是一个有用的命令，但它是一个有趣的命令，相当于你终端的桌面小工具。它很适合用来分散注意力和进行有趣的管道命令实验（尝试将 <code>ifconfig</code> 管道到 <code>cowsay</code>，或 <code>lsblk</code> 或 <code>mount</code>，或任何东西！）。如果你想让你的终端更有趣，试试 <code>cowsay</code>。</p><hr>`,34)),n("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/11/linux-cowsay-command"},{default:p(()=>[...s[7]||(s[7]=[a("https://opensource.com/article/21/11/linux-cowsay-command",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/don-watkins"},{default:p(()=>[...s[9]||(s[9]=[a("Don Watkins",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}